/* eslint-disable no-restricted-globals */
// self is the dedicated worker scope, not the browser window.
import {predictTrajectory} from "./orbitPhysics";

// Forecasts share the flight solver, but never occupy the interaction thread.
self.onmessage = ({data}) => {
  const {id, world, craft, options} = data;
  try {
    self.postMessage({
      id,
      paths: {...predictTrajectory(world, craft, options), source: "worker"}
    });
  } catch (error) {
    self.postMessage({
      id,
      paths: {current: [], maneuver: [], predictionError: error.message}
    });
  }
};
